def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = [sum(v == color for row in grid for v in row) for color in range(10)]
    bg = max(range(10), key=lambda color: counts[color])

    # Uniform non-background rows and columns are divider lines.
    div_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    div_cols = [
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg
    ]

    row_edges = [-1] + div_rows + [h]
    col_edges = [-1] + div_cols + [w]
    panels = []
    for ri in range(len(row_edges) - 1):
        r0, r1 = row_edges[ri] + 1, row_edges[ri + 1]
        for ci in range(len(col_edges) - 1):
            c0, c1 = col_edges[ci] + 1, col_edges[ci + 1]
            if r0 < r1 and c0 < c1:
                panels.append((r0, r1, c0, c1))

    source = max(
        panels,
        key=lambda p: sum(
            grid[r][c] != bg
            for r in range(p[0], p[1])
            for c in range(p[2], p[3])
        ),
    )
    r0, r1, c0, c1 = source
    pattern = [grid[r][c0:c1] for r in range(r0, r1)]

    out = [row[:] for row in grid]
    for pr0, pr1, pc0, pc1 in panels:
        if (pr1 - pr0, pc1 - pc0) == (len(pattern), len(pattern[0])):
            for dr in range(len(pattern)):
                out[pr0 + dr][pc0:pc1] = pattern[dr][:]
    return out
